(* [comment removed for export] *)
Ltac tr0 H a n H' :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) =>
  lazymatch goal with MU : munch ?W _ mm, X1 : rt3_apart ?q1, X2 : rt3_apart ?q2, RTF : 8388608 <= _ /\ 8388608 <= _ |- _ =>
    let Xa := fresh "Xa" in let Ya := fresh "Ya" in let D := fresh "D" in
    pose proof (X1 a n ltac:(cbn; repeat (first [left; reflexivity | right]))) as Xa;
    pose proof (X2 a n ltac:(cbn; repeat (first [left; reflexivity | right]))) as Ya;
    let A := lazymatch type of H with rw_cells _ _ ?A _ => A | ro_cells _ _ ?A _ => A end in
    let cs := lazymatch type of H with rw_cells _ _ _ ?cs => cs | ro_cells _ _ _ ?cs => cs end in
    assert (D : disjoint_from W A (Z.of_nat (cells_size cs)))
      by (cbn [disjoint_from cells_size csize Nat.add Z.of_nat Pos.of_succ_nat Pos.succ length]; repeat split;
          [clear - RTF; lia| clear - RTF; lia| clear - Xa; lia| clear - Ya; lia]);
    first [ lazymatch goal with WM : wmono asegs _ mm |- _ => pose proof (rw_cells_transport asegs _ _ mm _ _ H MU WM D) as H' end
          | pose proof (ro_cells_transport asegs _ _ mm _ _ H MU D) as H' ];
    clear Xa Ya D
  end end.
(* [comment removed for export] *)
Ltac rt_m2s H' := lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) => lazymatch goal with M2S : m2s_cells _ |- _ =>
  let Ma := fresh "Ma" in let Mb := fresh "Mb" in let Mc := fresh "Mc" in
  let Ma' := fresh "Ma'" in let Mb' := fresh "Mb'" in let Mc' := fresh "Mc'" in
  pose proof M2S as (Ma & Mb & Mc); tr0 Ma 0x226418 48 Ma'; tr0 Mb 0x2451b8 8 Mb'; tr0 Mc 0x245e98 32 Mc';
  assert (H' : m2s_cells mm) by exact (conj Ma' (conj Mb' Mc')); clear Ma Mb Mc Ma' Mb' Mc' end end.
Ltac rt_icm H' := lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) => lazymatch goal with ICM : icells_mc _ |- _ =>
  let Q1 := fresh "Q1" in let Q2 := fresh "Q2" in let Q3 := fresh "Q3" in let Q4 := fresh "Q4" in
  let R1 := fresh "R1" in let R2 := fresh "R2" in let R3 := fresh "R3" in let R4 := fresh "R4" in
  pose proof ICM as (Q1 & Q2 & Q3 & Q4); tr0 Q1 0x226418 48 R1; tr0 Q2 0x228358 8 R2; tr0 Q3 0x2451b8 8 R3; tr0 Q4 0x245e98 32 R4;
  assert (H' : icells_mc mm) by exact (conj R1 (conj R2 (conj R3 R4))); clear Q1 Q2 Q3 Q4 R1 R2 R3 R4 end end.
Ltac rt_icc H' := lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) => lazymatch goal with ICC : icells _ |- _ =>
  let Q1 := fresh "Q1" in let Q2 := fresh "Q2" in let Q3 := fresh "Q3" in let Q4 := fresh "Q4" in let Q5 := fresh "Q5" in
  let R1 := fresh "R1" in let R2 := fresh "R2" in let R3 := fresh "R3" in let R4 := fresh "R4" in let R5 := fresh "R5" in
  pose proof ICC as (Q1 & Q2 & Q3 & Q4 & Q5);
  tr0 Q1 0x226418 48 R1; tr0 Q2 0x226fa8 8 R2; tr0 Q3 0x228590 16 R3; tr0 Q4 0x2451b8 8 R4; tr0 Q5 0x245e98 32 R5;
  assert (H' : icells mm) by exact (conj R1 (conj R2 (conj R3 (conj R4 R5)))); clear Q1 Q2 Q3 Q4 Q5 R1 R2 R3 R4 R5 end end.
Ltac rt_ssp H' := lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) => lazymatch goal with SSP : ssp_cells _ ?g |- _ =>
  let Q1 := fresh "Q1" in let Q2 := fresh "Q2" in let R1 := fresh "R1" in let R2 := fresh "R2" in
  pose proof SSP as (Q1 & Q2); tr0 Q1 0x226b70 8 R1; tr0 Q2 0x797ed8 8 R2;
  assert (H' : ssp_cells mm g) by exact (conj R1 R2); clear Q1 Q2 R1 R2 end end.
(* [comment removed for export] *)
Ltac shadow_agree AGS := lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) => lazymatch goal with MU : munch ?W ?m0 mm |- _ =>
  assert (AGS : agree_on (fun x => 0x7fff8000 <= x < 0x10007fff8007) m0 mm)
    by (apply (agree_of_munch _ _ _ _ MU); intros y Hy; cbn [outside]; repeat split; lia) end end.
(* [comment removed for export] *)
Ltac tok_bytes H' := lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) =>
  lazymatch goal with MU : munch ?W ?m0 mm, BUFK : keep (bytes_at _ _ ?a ?l) |- _ =>
  assert (H' : bytes_at asegs mm a l)
    by (apply (bytes_at_keep _ _ _ _ _ BUFK MU); intros y Hy; rewrite ?length_app, ?length_map in Hy;
        cbn [length app map Z.of_nat Pos.of_succ_nat Pos.succ Nat.add] in Hy; cbn [outside]; repeat split; lia) end end.

(* [comment removed for export] *)
Ltac rom_cell RB H := lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) => lazymatch goal with MI : mem_inv asegs mm |- _ =>
  pose proof (ro_cells_image asegs mm _ _ MI RB ltac:(lia) ltac:(cbn; lia)) as H; cbn [length] in H end end.

Ltac if_sym := lazymatch goal with |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
  unfold bv_eqb, bv_ltu; rewrite ?unsigned_lit by lia; first [if_true | if_false | if_closed] end.
