Ltac tok_byte k C := let B := fresh "TB" in let T := fresh "TT" in
  tok_bytes B;
  lazymatch type of B with bytes_at _ ?mm ?a ?l =>
    let l1 := eval cbv [firstn] in (firstn k l) in let l2 := eval cbv [skipn] in (skipn k l) in
    pose proof (proj2 (proj1 (bytes_at_app asegs mm a l1 l2) B)) as T;
    let n := eval cbv in (Z.of_nat (length l1)) in change (Z.of_nat (length l1)) with n in T;
    lazymatch type of T with bytes_at _ _ ?a2 (?b :: ?rest) =>
      pose proof (ro_C1_of_bytes mm _ _ (proj1 (proj1 (bytes_at_app asegs mm a2 [b] rest) T))) as C end;
    clear B T end.
(* [comment removed for export] *)
Ltac tok_tail k T := let B := fresh "TB" in
  tok_bytes B;
  lazymatch type of B with bytes_at _ ?mm ?a ?l =>
    let l1 := eval cbv [firstn] in (firstn k l) in let l2 := eval cbv [skipn] in (skipn k l) in
    pose proof (proj2 (proj1 (bytes_at_app asegs mm a l1 l2) B)) as T;
    let n := eval cbv in (Z.of_nat (length l1)) in change (Z.of_nat (length l1)) with n in T; clear B end.

